-- German (deDE): the guide forever/reputation/bloodsail-buccaneers (forever/reputation/bloodsail-buccaneers.guide).
-- Written by `forge i18n guides sync deDE`, which keeps every translation (docs/TRANSLATING.md, "Guide texts").
-- Translate the right-hand sides; "" shows the English. Keep each {kind:id} as it is: the game shows its
-- name there in German (the English is listed above the line). A name the English has in the plural, as words,
-- may be written with the singular's token from its "plural, as words" line: "Bandidos ({npc:251918})", "{npc:251918} ×8".
-- A token marked "no name in this language" would show in English: write that name in German words instead.
-- The comments are rewritten by sync.
return {
	-- Guide
	["Bloodsail Buccaneers Reputation"] = "Ruf: Blutsegelbukaniere",
	-- {item:10030} Admiral's Hat · {area:35} Booty Bay
	["The pirate outfit and the {item:10030}, bought with a war against {area:35} and every goblin town."] = "Das Piratenoutfit und der {item:10030}, erkauft mit einem Krieg gegen {area:35} und jede Goblinstadt.",

	-- Step 1: Before you start
	["Before you start"] = "Bevor du anfängst",
	-- {area:35} Booty Bay · {area:976} Gadgetzan · {area:392} Ratchet · {area:2255} Everlook
	["Bloodsail standing goes up only by killing the people of {area:35}, and every kill costs you {area:35} 125 and the other goblin towns ({area:976}, {area:392}, {area:2255}, and in Forever likely Powderfuse) about 62 each. After the Bruisers this guide asks for, every goblin town is Hated: their guards attack you, and you lose their flight masters, inns, vendors and {area:976}'s and {area:2255}'s auction houses. Getting back takes longer than getting here (last step). Fly in, bind elsewhere, and do your goblin-town business first. The outfit and the hat need only Friendly; past that Bloodsail has nothing to give. {area:35}'s guards are not your enemies yet: tick At War for {area:35} in your reputation panel, then attack."] = "Der Ruf bei den Blutsegelbukanieren steigt nur, indem du die Leute von {area:35} tötest, und jeder Kill kostet dich 125 bei {area:35} und etwa 62 bei jeder anderen Goblinstadt ({area:976}, {area:392}, {area:2255} und in Forever wahrscheinlich Powderfuse). Nach den Bruisers, die dieser Guide verlangt, ist jede Goblinstadt Hasserfüllt: Ihre Wachen greifen dich an, und du verlierst Flugmeister, Gasthäuser, Händler und die Auktionshäuser von {area:976} und {area:2255}. Der Weg zurück dauert länger als der Weg hierher (letzter Schritt). Flieg hinein, binde woanders und erledige dein Goblinstadt-Geschäft zuerst. Outfit und Hut brauchen nur Freundlich; darüber hinaus hat Bloodsail nichts zu bieten. Die Wachen von {area:35} sind noch nicht deine Feinde: Setze in deinem Rufmenü bei {area:35} den Haken bei Im Krieg und greife dann an.",

	-- Step 2: Booty Bay Bruisers to Neutral
	-- plural, as words: Booty Bay Bruisers = {npc:4624} Booty Bay Bruiser
	["Booty Bay Bruisers to Neutral"] = "Booty Bay Bruisers bis Neutral",
	-- {area:35} Booty Bay · {area:327} Faldir's Cove · {zone:1417} Arathi Highlands
	["Look at your Bloodsail bar first. A new character starts Hated, 500 short of Hostile: 260 Bruisers to Neutral, at 25 each. But every {area:35} quest you did while leveling took five times its {area:35} reward off Bloodsail (An OOX of Your Own, Stranglethorn Fever and Facing Negolash 1,000 each), and every Bloodsail pirate you killed 25 more: after {area:35}'s quests you sit near the bottom of Hated, up to 1,680 Bruisers from Neutral. Divide what the bar still lacks to Hostile, plus 6,000, by 25. Bruisers (level 57) hit hard, net you and knock you back, and new ones come when a goblin calls for help. Fight on the path that turns left from the tunnel up to the blacksmith's house: two Bruisers patrol it and rarely meet. Once they are down, step into the house (or hit one of the goblins inside) and a fresh Bruiser comes running. Players manage 30 to 40 an hour. {area:35} is Hated after about 53 Bruisers from a fresh Neutral 500. At the New Year celebration the town's goblins are drunk and do not fight back. The Blackwater crew at {area:327} in the {zone:1417} (level 37-40) are easier but pay only 5 each. Do not kill Bloodsail pirates: each costs 25."] = "Sieh dir zuerst deine Bloodsail-Leiste an. Ein neuer Charakter beginnt Hasserfüllt, 500 vor Feindselig: 260 Bruisers bis Neutral, je 25. Aber jede Quest von {area:35}, die du beim Leveln gemacht hast, hat Bloodsail das Fünffache ihrer {area:35}-Belohnung abgezogen (An OOX of Your Own, Stranglethorn Fever und Facing Negolash je 1.000), und jeder getötete Bloodsail-Pirat weitere 25: Nach den Quests von {area:35} stehst du nahe dem Boden von Hasserfüllt, bis zu 1.680 Bruisers von Neutral entfernt. Teile, was der Leiste bis Feindselig noch fehlt, plus 6.000, durch 25. Bruisers (Stufe 57) schlagen hart, fangen dich ein und werfen dich zurück, und neue kommen, wenn ein Goblin um Hilfe ruft. Kämpfe auf dem Pfad, der vom Tunnel links zum Haus des Schmieds hinaufführt: Zwei Bruisers patrouillieren dort und treffen selten aufeinander. Sind sie erledigt, tritt ins Haus (oder schlage einen der Goblins darin), und ein frischer Bruiser kommt angerannt. Spieler schaffen 30 bis 40 pro Stunde. {area:35} ist nach etwa 53 Bruisers ab frischem Neutral 500 Hasserfüllt. Beim Neujahrsfest sind die Goblins der Stadt betrunken und wehren sich nicht. Die Blackwater-Mannschaft bei {area:327} in {zone:1417} (Stufe 37-40) ist leichter, zahlt aber nur je 5. Töte keine Bloodsail-Piraten: Jeder kostet 25.",
	["the path to the smithy"] = "der Pfad zur Schmiede",

	-- Step 3: Dressing the Part
	-- {npc:2546} Fleet Master Firallon · {area:1757} Crimson Veil · {area:35} Booty Bay · {item:22746} Buccaneer's Uniform · {item:22742} Bloodsail Shirt
	["At Neutral the Bloodsail crew stop attacking you. {npc:2546} is aboard the {area:1757}, the pirate ship anchored south of {area:35}, on its middle deck. Swim out; take the quest and hand it in on the spot for the {item:22746}: the {item:22742}, Sash, Pants and Boots."] = "Bei Neutral greift dich die Bloodsail-Mannschaft nicht mehr an. {npc:2546} ist an Bord der {area:1757}, dem Piratenschiff südlich von {area:35}, auf dem mittleren Deck. Schwimm hinaus; nimm die Quest an und gib sie auf der Stelle ab für das {item:22746}: den {item:22742}, Schärpe, Hose und Stiefel.",
	-- {npc:2546} Fleet Master Firallon · {item:22746} Buccaneer's Uniform
	["{npc:2546}: the {item:22746}"] = "{npc:2546}: das {item:22746}",

	-- Step 4: Bruisers to Friendly
	["Bruisers to Friendly"] = "Bruisers bis Freundlich",
	["Neutral to Friendly is 3,000 more: 120 Bruisers. Friendly is the last standing that unlocks anything."] = "Von Neutral bis Freundlich sind es 3.000 mehr: 120 Bruisers. Freundlich ist der letzte Stand, der etwas freischaltet.",

	-- Step 5: Avast Ye, Scallywag
	-- {area:35} Booty Bay
	["\"Pretty Boy\" Duncan, a Bloodsail pirate, stands on the beach north of {area:35}. {area:35} players kill him for a quest: if he is not there, wait for him. He has a quest for you from level 55, while {area:35} is below Neutral; it is done once you are Friendly with the Bloodsail and Hated with {area:35}."] = "„Pretty Boy“ Duncan, ein Bloodsail-Pirat, steht am Strand nördlich von {area:35}. Spieler von {area:35} töten ihn für eine Quest: Ist er nicht da, warte auf ihn. Er hat ab Stufe 55 eine Quest für dich, solange {area:35} unter Neutral ist; sie ist erledigt, wenn du bei den Bloodsail Freundlich und bei {area:35} Hasserfüllt bist.",
	-- {npc:2546} Fleet Master Firallon · {area:1757} Crimson Veil
	["{npc:2546}, on the {area:1757}: 25"] = "{npc:2546}, auf der {area:1757}: 25",

	-- Step 6: Avast Ye, Admiral!
	-- {npc:2496} Baron Revilgaz · {npc:2487} Fleet Master Seahorn · {area:35} Booty Bay
	["{npc:2496} and {npc:2487} stand on the top floor of the {area:35} inn, out on the balcony. Both are level 60 and Bruisers come to their aid: clear the stairs first and pull them one at a time. They come back, so a friend can kill them too."] = "{npc:2496} und {npc:2487} stehen im obersten Stockwerk des Gasthauses von {area:35}, draußen auf dem Balkon. Beide sind Stufe 60, und Bruisers kommen ihnen zu Hilfe: Räume zuerst die Treppen und ziehe sie einzeln heran. Sie kommen wieder, ein Freund kann sie also auch töten.",

	-- Step 7: The Admiral's Hat
	-- {item:10030} Admiral's Hat
	["The {item:10030}"] = "Der {item:10030}",
	-- {item:12185} Bloodsail Admiral's Hat · {area:35} Booty Bay · {zone:1418} Badlands
	["Back to Firallon for the {item:12185} (in Classic its use calls a parrot to your shoulder): 200 more Bloodsail and 1,000 less {area:35}. Bruisers pay 25 only up to the end of Honored and Jazzrik, a lone goblin in the {zone:1418}, 5 up to the end of Revered; no quest is left, so Exalted cannot be reached."] = "Zurück zu Firallon für den {item:12185} (in Classic ruft seine Benutzung einen Papagei auf deine Schulter): 200 mehr Bloodsail und 1.000 weniger {area:35}. Bruisers zahlen nur bis zum Ende von Wohlwollend 25 und Jazzrik, ein einzelner Goblin in der {zone:1418}, bis zum Ende von Respektvoll 5; es bleibt keine Quest, Ehrfürchtig ist also nicht zu erreichen.",

	-- Step 8: The way back
	["The way back"] = "Der Weg zurück",
	-- {area:392} Ratchet · {area:35} Booty Bay · {area:976} Gadgetzan · {area:2255} Everlook · {npc:14637} Zorbin Fandazzle · {zone:1444} Feralas
	["Every goblin town is now Hated. Forever's quest data takes the town reputation off the four goblin amends quests outside {area:392}, {area:35}, {area:976} and {area:2255}, so the climb back is the Cartel's own: {npc:14637} in {zone:1444} serves everyone, and his Zapped Giants quests pay 25 to every town at once; Bloodsail pirates give {area:35} 5 each up to the end of Neutral (and cost Bloodsail 25); Southsea pirates and the Venture Co. in Stranglethorn give the towns 5 each. The Steamwheedle Cartel guide has the details. Expect it to take longer than the war did."] = "Jede Goblinstadt ist jetzt Hasserfüllt. Die Questdaten von Forever ziehen den vier Goblin-Wiedergutmachungsquests außerhalb von {area:392}, {area:35}, {area:976} und {area:2255} den Stadtruf ab, der Aufstieg zurück ist also der des Kartells selbst: {npc:14637} in {zone:1444} bedient alle, und seine Zapped-Giants-Quests zahlen 25 an jede Stadt zugleich; Bloodsail-Piraten geben {area:35} je 5 bis zum Ende von Neutral (und kosten Bloodsail 25); Südsee-Piraten und die Venture Co. in Stranglethorn geben den Städten je 5. Der Guide zum Dampfdruckkartell hat die Einzelheiten. Rechne damit, dass es länger dauert als der Krieg.",
	-- {npc:14637} Zorbin Fandazzle
	["{npc:14637}: Zapped Giants, open to the Hated"] = "{npc:14637}: Zapped Giants, offen für Hasserfüllte",
}
